      "causa_raiz": "Alocação massiva de lixo na memória managed por frame dentro do método Update, decorrente de concatenação contínua de strings em laço (s += i.ToString()) e chamadas repetitivas a GameObject.FindObjectsOfType<GameObject>(), gerando ~2.6 MB de garbage por frame e disparando pausas severas de GC.Collect (17.94ms).",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");
        private MaterialPropertyBlock _propertyBlock;
        private readonly List<GameObject> _spawnedObjects = new List<GameObject>();

        private void Awake()
        {
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var emptyGo = new GameObject("Empty_" + i);
                _spawnedObjects.Add(emptyGo);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    int count = _spawnedObjects.Count;
                    for (int j = 0; j < count; j++)
                    {
                        if (_spawnedObjects[j] != null)
                        {
                            _ = _spawnedObjects[j].activeSelf;
                        }
                    }
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            _spawnedObjects.Add(clone);

            if (useUniqueMaterials)
            {
                var rend = clone.GetComponent<Renderer>();
                if (rend != null)
                {
                    rend.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    rend.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, o texto (string) é imutável. Toda vez que fazemos 's += i.ToString()', uma nova string é criada na memória e a anterior vira lixo. Fazer isso milhares de vezes por segundo no Update sobrecarrega o Garbage Collector (coletor de lixo da memória), que precisa congelar o jogo por vários milissegundos para limpar a sujeira acumulada, causando quedas bruscas de quadros (micro-engasgos). Além disso, usar 'FindObjectsOfType' a cada frame força a Unity a varrer toda a cena procurando objetos, alocando um array novo todas as vezes. A solução é eliminar essas alocações repetitivas no Update, armazenar referências em uma lista prévia e utilizar 'MaterialPropertyBlock' para alterar cores sem instanciar novos materiais."
    }
  ],
  "dicas_level_design": null
}

